package com.autojobapply.tracking;
import com.autojobapply.model.*; import java.io.*; import java.nio.file.*; import java.sql.*; import java.time.*; import java.util.*;
public final class ApplicationTracker implements AutoCloseable { private final Connection conn; public ApplicationTracker(Path db)throws SQLException{conn=DriverManager.getConnection("jdbc:sqlite:"+db.toAbsolutePath());}
 public void saveEmployer(String token,String company,String boardUrl,String apiUrl,String source,boolean valid){try(PreparedStatement p=conn.prepareStatement("INSERT INTO greenhouse_employers(board_token,company,board_url,api_url,source,validated,discovered_at,validated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(board_token) DO UPDATE SET company=excluded.company,validated=excluded.validated,validated_at=excluded.validated_at")){String now=Instant.now().toString();p.setString(1,token);p.setString(2,company);p.setString(3,boardUrl);p.setString(4,apiUrl);p.setString(5,source);p.setInt(6,valid?1:0);p.setString(7,now);p.setString(8,valid?now:null);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public void enqueue(ScoredJob job){String token=job.job().source().equals("Greenhouse")?job.job().company().toLowerCase().replaceAll("\\s+", "-"):null;enqueue(token,job);}
 public void enqueue(String boardToken,ScoredJob job){if(!job.eligible())return;try(PreparedStatement p=conn.prepareStatement("INSERT INTO application_queue(identity,priority,state,queued_at,updated_at,board_token,greenhouse_job_id,application_url) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING")){String now=Instant.now().toString();p.setString(1,job.job().identity());p.setInt(2,job.score());p.setString(3,"READY_TO_APPLY");p.setString(4,now);p.setString(5,now);p.setString(6,boardToken);p.setString(7,job.job().jobId());p.setString(8,job.job().applicationUrl());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public void initialize()throws SQLException{try(Statement s=conn.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS applications (identity TEXT PRIMARY KEY, company TEXT NOT NULL, title TEXT NOT NULL, location TEXT, job_id TEXT, score INTEGER, matching TEXT, missing TEXT, source TEXT, listing_url TEXT, application_url TEXT, discovered_at TEXT, attempted_at TEXT, submitted_at TEXT, status TEXT NOT NULL, confirmation TEXT, reason TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS application_validation (identity TEXT PRIMARY KEY, company TEXT NOT NULL, application_url TEXT, match_score INTEGER, validated_fields TEXT, unresolved_fields TEXT,visible_errors TEXT,resume_attached INTEGER,validation_result TEXT NOT NULL,submit_attempted INTEGER NOT NULL,confirmation TEXT,recorded_at TEXT NOT NULL)");s.executeUpdate("CREATE TABLE IF NOT EXISTS greenhouse_employers (board_token TEXT PRIMARY KEY, company TEXT, board_url TEXT, api_url TEXT, source TEXT, validated INTEGER NOT NULL, discovered_at TEXT NOT NULL, validated_at TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS greenhouse_jobs (board_token TEXT NOT NULL, job_id TEXT NOT NULL, company TEXT, title TEXT, application_url TEXT, location TEXT, description TEXT, discovered_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, PRIMARY KEY(board_token,job_id))");s.executeUpdate("CREATE TABLE IF NOT EXISTS application_queue (identity TEXT PRIMARY KEY, priority INTEGER NOT NULL, state TEXT NOT NULL, queued_at TEXT NOT NULL, updated_at TEXT NOT NULL, board_token TEXT, greenhouse_job_id TEXT, application_url TEXT)");s.executeUpdate("CREATE TABLE IF NOT EXISTS discovery_state (state_key TEXT PRIMARY KEY, state_value TEXT NOT NULL, updated_at TEXT NOT NULL)");if(!queueColumn("board_token"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN board_token TEXT");if(!queueColumn("greenhouse_job_id"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN greenhouse_job_id TEXT");if(!queueColumn("application_url"))s.executeUpdate("ALTER TABLE application_queue ADD COLUMN application_url TEXT");s.executeUpdate("CREATE UNIQUE INDEX IF NOT EXISTS uq_queue_greenhouse ON application_queue(board_token,greenhouse_job_id) WHERE board_token IS NOT NULL AND greenhouse_job_id IS NOT NULL");}}
 private boolean queueColumn(String name)throws SQLException{try(Statement s=conn.createStatement();ResultSet r=s.executeQuery("PRAGMA table_info(application_queue)")){while(r.next())if(name.equalsIgnoreCase(r.getString("name")))return true;return false;}}
 public void saveGreenhouseJob(String token, Job j){if(token==null||token.isBlank()||j.jobId()==null||j.jobId().isBlank())throw new IllegalArgumentException("board token and job id required");try(Statement s=conn.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS greenhouse_jobs (board_token TEXT NOT NULL, job_id TEXT NOT NULL, company TEXT, title TEXT, application_url TEXT, location TEXT, description TEXT, discovered_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, PRIMARY KEY(board_token,job_id))");}catch(SQLException e){throw new IllegalStateException(e);}try(PreparedStatement p=conn.prepareStatement("INSERT INTO greenhouse_jobs(board_token,job_id,company,title,application_url,location,description,discovered_at,last_seen_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(board_token,job_id) DO UPDATE SET company=COALESCE(NULLIF(excluded.company,''),greenhouse_jobs.company),title=COALESCE(NULLIF(excluded.title,''),greenhouse_jobs.title),application_url=COALESCE(NULLIF(excluded.application_url,''),greenhouse_jobs.application_url),location=COALESCE(NULLIF(excluded.location,''),greenhouse_jobs.location),description=COALESCE(NULLIF(excluded.description,''),greenhouse_jobs.description),last_seen_at=excluded.last_seen_at")){String now=Instant.now().toString();p.setString(1,token);p.setString(2,j.jobId());p.setString(3,j.company());p.setString(4,j.title());p.setString(5,j.applicationUrl());p.setString(6,j.location());p.setString(7,j.description());p.setString(8,now);p.setString(9,now);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}
 public int greenhouseJobCount()throws SQLException{try(Statement s=conn.createStatement();ResultSet r=s.executeQuery("SELECT count(*) FROM greenhouse_jobs")){return r.getInt(1);}}
 public List<ScoredJob> readyQueuedJobs()throws SQLException{String sql="SELECT q.priority,a.company,a.title,a.location,a.job_id,a.matching,a.missing,a.source,a.listing_url,COALESCE(q.application_url,a.application_url,g.application_url),g.description FROM application_queue q JOIN applications a ON a.identity=q.identity LEFT JOIN greenhouse_jobs g ON g.board_token=q.board_token AND g.job_id=q.greenhouse_job_id WHERE q.state='READY_TO_APPLY' AND a.source='Greenhouse'";try(PreparedStatement p=conn.prepareStatement(sql);ResultSet r=p.executeQuery()){List<ScoredJob> jobs=new ArrayList<>();while(r.next())jobs.add(queued(r));return jobs;}}
 public Optional<ScoredJob> queuedJob(String identity)throws SQLException{String sql="SELECT q.priority,a.company,a.title,a.location,a.job_id,a.matching,a.missing,a.source,a.listing_url,COALESCE(q.application_url,a.application_url,g.application_url),g.description FROM application_queue q JOIN applications a ON a.identity=q.identity LEFT JOIN greenhouse_jobs g ON g.board_token=q.board_token AND g.job_id=q.greenhouse_job_id WHERE q.identity=? AND q.state='READY_TO_APPLY'";try(PreparedStatement p=conn.prepareStatement(sql)){p.setString(1,identity);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();Job job=new Job(r.getString(8),r.getString(2),r.getString(3),r.getString(4),r.getString(11),r.getString(5),r.getString(9),r.getString(10));return Optional.of(new ScoredJob(job,r.getInt(1),split(r.getString(6)),split(r.getString(7)),true,"queued-existing-match",List.of()));}}}
 public Optional<String> queueState(String identity)throws SQLException{try(PreparedStatement p=conn.prepareStatement("SELECT state FROM application_queue WHERE identity=?")){p.setString(1,identity);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(r.getString(1)):Optional.empty();}}}
 private ScoredJob queued(ResultSet r)throws SQLException{Job job=new Job(r.getString(8),r.getString(2),r.getString(3),r.getString(4),r.getString(11),r.getString(5),r.getString(9),r.getString(10));return new ScoredJob(job,r.getInt(1),split(r.getString(6)),split(r.getString(7)),true,"queued-existing-match",List.of());}
 public void markQueueIneligible(String identity)throws SQLException{try(PreparedStatement p=conn.prepareStatement("UPDATE application_queue SET state='INELIGIBLE',updated_at=? WHERE identity=? AND state='READY_TO_APPLY'")){p.setString(1,Instant.now().toString());p.setString(2,identity);p.executeUpdate();}}
 private List<String> split(String value){return value==null||value.isBlank()?List.of():Arrays.stream(value.split(";")).filter(v->!v.isBlank()).toList();}
 public String discoveryCursor(String key)throws SQLException{try(PreparedStatement p=conn.prepareStatement("SELECT state_value FROM discovery_state WHERE state_key=?")){p.setString(1,key);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):"";}}}
 public void saveDiscoveryCursor(String key,String value)throws SQLException{try(PreparedStatement p=conn.prepareStatement("INSERT INTO discovery_state(state_key,state_value,updated_at) VALUES(?,?,?) ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=excluded.updated_at")){p.setString(1,key);p.setString(2,value);p.setString(3,Instant.now().toString());p.executeUpdate();}}
 public boolean isKnown(Job j)throws SQLException{try(PreparedStatement p=conn.prepareStatement("SELECT 1 FROM applications WHERE identity=? AND status IN ('SUBMITTED','APPLYING','MATCHED','UNSUPPORTED','BLOCKED')")){p.setString(1,j.identity());return p.executeQuery().next();}}
 public void record(ScoredJob sj,ApplicationStatus status,String reason){Job j=sj.job();String sql="INSERT INTO applications(identity,company,title,location,job_id,score,matching,missing,source,listing_url,application_url,discovered_at,attempted_at,submitted_at,status,reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(identity) DO UPDATE SET score=excluded.score, matching=excluded.matching, missing=excluded.missing, attempted_at=excluded.attempted_at, status=excluded.status, reason=excluded.reason";try(PreparedStatement p=conn.prepareStatement(sql)){String now=Instant.now().toString();p.setString(1,j.identity());p.setString(2,j.company());p.setString(3,j.title());p.setString(4,j.location());p.setString(5,j.jobId());p.setInt(6,sj.score());p.setString(7,String.join(";",sj.matchingSkills()));p.setString(8,String.join(";",sj.missingSkills()));p.setString(9,j.source());p.setString(10,j.listingUrl());p.setString(11,j.applicationUrl());p.setString(12,now);p.setString(13,status==ApplicationStatus.MATCHED||status==ApplicationStatus.SKIPPED?null:now);p.setString(14,status==ApplicationStatus.SUBMITTED?now:null);p.setString(15,status.name());p.setString(16,reason);p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Could not save application record",e);}}
 public void recordValidation(ScoredJob sj,com.autojobapply.application.FormValidationResult validation,boolean submitAttempted,String confirmation){if(validation==null)return;String sql="INSERT INTO application_validation(identity,company,application_url,match_score,validated_fields,unresolved_fields,visible_errors,resume_attached,validation_result,submit_attempted,confirmation,recorded_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(identity) DO UPDATE SET validated_fields=excluded.validated_fields,unresolved_fields=excluded.unresolved_fields,visible_errors=excluded.visible_errors,resume_attached=excluded.resume_attached,validation_result=excluded.validation_result,submit_attempted=excluded.submit_attempted,confirmation=excluded.confirmation,recorded_at=excluded.recorded_at";try(PreparedStatement p=conn.prepareStatement(sql)){Job j=sj.job();p.setString(1,j.identity());p.setString(2,j.company());p.setString(3,j.applicationUrl());p.setInt(4,sj.score());p.setString(5,String.join(";",validation.validatedFields()));p.setString(6,String.join(";",validation.unresolvedFields()));p.setString(7,String.join(";",validation.visibleErrors()));p.setInt(8,validation.resumeAttached()?1:0);p.setString(9,validation.valid()?"VALID":"INVALID");p.setInt(10,submitAttempted?1:0);p.setString(11,confirmation);p.setString(12,Instant.now().toString());p.executeUpdate();}catch(SQLException e){throw new IllegalStateException("Could not save validation evidence",e);}}
 public void exportCsv(Path csv)throws SQLException,IOException{Path parent=csv.getParent();if(parent!=null)Files.createDirectories(parent);try(BufferedWriter out=Files.newBufferedWriter(csv);Statement s=conn.createStatement();ResultSet r=s.executeQuery("SELECT company,title,location,job_id,score,matching,missing,source,listing_url,application_url,discovered_at,attempted_at,submitted_at,status,confirmation,reason FROM applications ORDER BY score DESC")){out.write("company,title,location,job_id,match_score,matching_qualifications,missing_qualifications,discovery_source,original_job_url,application_url,date_discovered,date_attempted,date_submitted,status,confirmation,reason\n");while(r.next()){for(int i=1;i<=16;i++){if(i>1)out.write(',');out.write(csv(r.getString(i)));}out.write('\n');}}}
 private String csv(String v){return "\""+(v==null?"":v.replace("\"","\"\""))+"\"";} public void close()throws SQLException{conn.close();}}
